+public class CacheKeySerializer {
+
+    public static String serialize(String method, String url, Map<String, String> headers, byte[] body) throws NoSuchAlgorithmException {
+        if (method.trim().isEmpty()) {
+            throw new ValueError("Method cannot be empty");
+        }
+
+        // Normalize URL
+        String normalizedUrl = normalizeUrl(url);
+
+        // Normalize headers
+        String normalizedHeaders = normalizeHeaders(headers);
+
+        // Normalize body
+        String normalizedBody = body == null ? "" : "body:" + bytesToHex(body);
+
+        return method.toUpperCase() + "-" + normalizedUrl + "-" + normalizedHeaders + "-" + normalizedBody;
+    }
+
+    private static String normalizeUrl(String url) {
+        try {
+            java.net.URI uri = new java.net.URI(url);
+            return uri.toString().toLowerCase();
+        } catch (java.net.URISyntaxException e) {
+            throw new ValueError("Invalid URL: " + url);
+        }
+    }
+
+    private static String normalizeHeaders(Map<String, String> headers) {
+        List<Map.Entry<String, String>> sortedEntries = headers.entrySet()
+                .stream()
+                .sorted((e1, e2) -> e1.getKey().compareTo(e2.getKey()))
+                .collect(Collectors.toList());
+
+        StringBuilder sb = new StringBuilder();
+        for (Map.Entry<String, String> entry : sortedEntries) {
+            sb.append(entry.getKey()).append(":").append(entry.getValue()).append(",");
+        }
+        if (!sb.isEmpty()) {
+            sb.setLength(sb.length() - 1); // Remove trailing comma
+        }
+        return sb.toString();
+    }
+
+    private static String bytesToHex(byte[] bytes) {
+        StringBuilder hexString = new StringBuilder();
+        for (byte b : bytes) {
+            String hex = Integer.toHexString(0xff & b);
+            if (hex.length() == 1) {
+                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
+    }
